import { redirect } from "next/navigation";
import Link from "next/link";
import { requireVendor } from "@/lib/dal";
import { prisma } from "@/lib/prisma";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
export default async function VendorDashboardPage() { const user = await requireVendor(); const vendor = await prisma.vendor.findFirst({ where: { organization: { ownerId: user.id } }, include: { organization: { include: { kycCases: { orderBy: { createdAt: "desc" }, take: 1 } } } } }); if (!vendor || vendor.status !== "APPROVED") redirect("/admin/unauthorized"); const status = vendor.organization.kycCases[0]?.status || "PENDING"; return <main className="mx-auto flex max-w-6xl flex-col gap-8"><div className="flex flex-wrap items-end justify-between gap-4"><div><p className="text-sm text-muted-foreground">Vendor workspace</p><h1 className="text-3xl font-semibold">{vendor.businessName}</h1></div><div className="flex gap-3"><Button asChild><Link href="/vendor/products/create">Add New Product</Link></Button><Button variant="outline" asChild><Link href="/vendor/kyc">Update KYC Documents</Link></Button></div></div><Card><CardContent className="flex items-center justify-between gap-4 p-6"><div><p className="text-sm text-muted-foreground">KYC status</p><p className="mt-1 text-xl font-semibold">{status.replace("_", " ")}</p></div><Badge>{status}</Badge></CardContent></Card><div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">{[["Total products","0"],["Total orders","0"],["Pending orders","0"],["Total revenue","₹0"]].map(([label,value]) => <Card key={label}><CardHeader><CardTitle className="text-sm font-medium text-muted-foreground">{label}</CardTitle></CardHeader><CardContent><p className="text-3xl font-semibold">{value}</p></CardContent></Card>)}</div><Card><CardHeader><CardTitle>Recent orders</CardTitle></CardHeader><CardContent><p className="text-sm text-muted-foreground">No orders have been placed yet.</p></CardContent></Card></main>; }
